INSERT OR REPLACE INTO "Ability" ("AbilityID","KeyName","Name","InternalID","Description","IconID","Implementation","LastTimeRowUpdated") VALUES (23,'Mastery of Stealth','Mastery of Stealth',151,'Modifies stealth detection and stealth movement. Camouflage counters the Mastery of Stealth bonus, allowing an archer to only be seen at the normal range. Doesn''t affect detect hidden classes when they are detecting other detect hidden classes. (Meaning it has no affect on assassins detecting assassins.)',0,'DOL.GS.RealmAbilities.AtlasOF_MasteryOfStealth','2000-01-01 00:00:00');
