INSERT OR REPLACE INTO "Ability" ("AbilityID","KeyName","Name","InternalID","Description","IconID","Implementation","LastTimeRowUpdated") VALUES (371,'AtlasOF_CripplingPlague','Crippling Plague',3038,'Instant plague on an enemy: it slows the target by 10%, rising every second to 95% over 10 seconds, then bursts for 150 poison damage to enemies within 250 units of the target. Curing it first stops the burst. 1 minute reuse.',3425,'DOL.GS.RealmAbilities.AtlasOF_CripplingPlague','2000-01-01 00:00:00');
